"sendDiagnostics.privacyNotice": "Isto envia um pacote de depuração para um armazenamento interno da Nous (não é um paste público). Ele inclui informações do sistema (SO, versões, provedor, quais chaves de API estão configuradas — nunca as chaves em si) e os logs completos do agente, do gateway e do desktop (até 512 KB cada), que provavelmente contêm conteúdo de conversas, saídas de ferramentas e caminhos de arquivos. Segredos são ocultados antes do envio. O pacote só pode ser visto pela equipe da Nous e por moderadores autorizados do Discord, e é excluído automaticamente após 14 dias.",
