"settings.fieldDescriptions.agent.imageInputMode": "Controla como os anexos de imagem são enviados ao modelo.",
"settings.fieldDescriptions.agent.maxTurns": "Limite máximo de turnos de chamadas de ferramentas antes que o Hermes interrompa uma execução.",
"settings.fieldDescriptions.approvals.mode": "Como o Hermes lida com comandos que precisam de aprovação explícita.",
"settings.fieldDescriptions.approvals.timeout": "Quanto tempo os pedidos de aprovação aguardam antes de expirar.",
"settings.fieldDescriptions.auxiliary.compression.timeout": "Segundos de espera pelo modelo auxiliar de compressão por chamada (padrão 120). Aumente para modelos locais lentos.",
"settings.fieldDescriptions.browser.useRealProfile": "A navegação local usa seus logins reais. O Hermes copia o perfil do seu navegador padrão (cookies, logins, preferências) para um snapshot gerenciado e o controla com o Chromium incluído — seu perfil ativo nunca é aberto diretamente, e a cópia é atualizada a partir dele a cada execução. Também permite que o agente abra uma sessão local com o perfil real quando solicitado, mesmo com um backend de navegador na nuvem configurado. Somente navegadores Chromium (Chrome, Edge, Brave, Brave Origin, Chromium) são suportados; um navegador padrão não Chromium falha com uma mensagem clara. Desativado por padrão.",
"settings.fieldDescriptions.checkpoints.enabled": "Cria snapshots de reversão antes de editar arquivos.",
"settings.fieldDescriptions.codeExecution.mode": "O quão estritamente a execução de código fica restrita ao projeto atual.",
"settings.fieldDescriptions.compression.codexGpt55Autoraise": "Eleva a compressão para 85% nos modelos ChatGPT Codex OAuth suportados.",
"settings.fieldDescriptions.compression.enabled": "Resume o contexto mais antigo quando as conversas ficam grandes.",
"settings.fieldDescriptions.context.engine": "Estratégia para gerenciar conversas longas perto do limite de contexto.",
"settings.fieldDescriptions.desktop.repoScanEnabled": "Procura repositórios Git em pastas locais para exibir em Projetos.",
"settings.fieldDescriptions.desktop.repoScanExcludePaths": "Pastas (e suas subpastas) a ignorar durante a descoberta de repositórios.",
"settings.fieldDescriptions.desktop.repoScanRoots": "Pastas a verificar. Deixe vazio para verificar seu diretório pessoal.",
"settings.fieldDescriptions.display.personality": "Estilo padrão do assistente para novas sessões.",
"settings.fieldDescriptions.display.showReasoning": "Mostra seções de raciocínio quando o backend as fornece.",
"settings.fieldDescriptions.fallbackProviders": "Entradas provider:model de reserva a tentar se o modelo padrão falhar.",
"settings.fieldDescriptions.fileReadMaxChars": "Máximo de caracteres que o Hermes pode ler em uma solicitação de arquivo.",
"settings.fieldDescriptions.memory.memoryEnabled": "Salva memórias duradouras que podem ajudar em sessões futuras.",
"settings.fieldDescriptions.memory.userProfileEnabled": "Mantém um perfil compacto das preferências do usuário.",
"settings.fieldDescriptions.model": "Usado em novos chats, a menos que você escolha outro modelo no editor.",
"settings.fieldDescriptions.modelContextLength": "Substitui a janela de contexto detectada apenas do modelo de chat PRINCIPAL (tokens). Deixe em 0 para usar o valor detectado do modelo selecionado. Não afeta modelos auxiliares/MoA.",
"settings.fieldDescriptions.security.redactSecrets": "Oculta segredos detectados do conteúdo visível ao modelo, quando possível.",
"settings.fieldDescriptions.stt.echoTranscripts": "Publica a transcrição 🎙️ bruta das mensagens de voz de volta no chat.",
"settings.fieldDescriptions.stt.elevenlabs.languageCode": "Código de idioma ISO-639-3 opcional. Em branco deixa a ElevenLabs detectar automaticamente.",
"settings.fieldDescriptions.stt.enabled": "Ativa a transcrição de fala local ou por provedor.",
"settings.fieldDescriptions.terminal.cwd": "Pasta de projeto padrão para trabalho com ferramentas e terminal.",
