"settings.fieldDescriptions.terminal.envPassthrough": "Variáveis de ambiente a repassar para a execução de ferramentas.",
"settings.fieldDescriptions.terminal.modalImage": "Imagem usada quando o backend de execução é Modal.",
"settings.fieldDescriptions.terminal.persistentShell": "Mantém o estado do shell entre comandos quando o backend oferece suporte.",
"settings.fieldDescriptions.terminal.singularityImage": "Imagem usada quando o backend de execução é Singularity.",
"settings.fieldDescriptions.timezone": "Identificador de fuso horário IANA. Em branco usa o fuso horário do sistema.",
"settings.fieldDescriptions.tts.neutts.device": "Dispositivo de inferência local para o NeuTTS.",
"settings.fieldDescriptions.tts.xai.autoSpeechTags": "Deixa um LLM inserir tags de áudio expressivas ([laughing], [sighs]) no roteiro antes da síntese.",
"settings.fieldDescriptions.tts.xai.bitRate": "Taxa de bits do MP3 em bps. Só se aplica quando o codec é mp3.",
"settings.fieldDescriptions.tts.xai.language": "Código do idioma falado (ex.: en, pt-BR) ou \"auto\" para detecção automática.",
"settings.fieldDescriptions.tts.xai.optimizeStreamingLatency": "Equilíbrio entre latência e qualidade. 0 = melhor qualidade, 2 = menor latência.",
"settings.fieldDescriptions.tts.xai.sampleRate": "Taxa de amostragem de áudio em Hz. Maior = melhor qualidade, arquivos maiores.",
"settings.fieldDescriptions.tts.xai.speed": "Velocidade de reprodução. 0.7 = mais lenta, 1.0 = normal, 1.5 = mais rápida.",
"settings.fieldDescriptions.tts.xai.voiceId": "ID de voz da xAI (ex.: eve) ou um ID de voz personalizado.",
"settings.fieldDescriptions.updates.nonInteractiveLocalChanges": "Quando o Hermes se atualiza pelo app (sem prompt no terminal), mantém as edições locais no código-fonte (stash) ou as descarta (discard). Atualizações pelo terminal sempre perguntam.",
"settings.fieldDescriptions.voice.autoTts": "Fala automaticamente as respostas do assistente.",
"settings.fieldDescriptions.voice.gptLive.instructions": "Frases extras para a persona de voz ao vivo (tom, ritmo, idioma). O Hermes mantém seu próprio prompt de sistema.",
"settings.fieldDescriptions.voice.gptLive.voice": "Voz para o modo GPT-Live. IDs de voz personalizados são aceitos.",
"settings.fieldDescriptions.voice.voiceChatMode": "chained: fala para texto → Hermes → texto para fala com os provedores abaixo. gpt-live: um único modelo de voz full-duplex da OpenAI (gpt-live-1) ouve e fala, e repassa cada solicitação real ao Hermes — qualquer modelo que você tenha selecionado responde com o conjunto completo de ferramentas. Requer uma chave de API da OpenAI; a camada de voz custa US$ 0,05 por minuto.",
