export default {
  id: 'hermes-ptbr-desktop',
  name: 'Português (Brasil)',
  description: 'Pacote de idioma pt-BR para todo o Hermes Desktop (vale para conexão local e VPS).',
  defaultEnabled: true,
  register(ctx) {
    const reg = (ctx.i18n && ctx.i18n.registerAppLocale) ? ctx.i18n.registerAppLocale.bind(ctx.i18n) : host.i18n.registerAppLocale
    const dispose = reg('pt', { endonym: 'Português (Brasil)', englishName: 'Portuguese (Brazil)', rtl: false, translations: TRANSLATIONS })
    if (typeof dispose === 'function' && ctx.onDispose) ctx.onDispose(dispose)
  }
}
